import React, { useEffect, useState, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { GoogleMap, Marker, useJsApiLoader } from "@react-google-maps/api";
import axios from "axios";
import { io } from "socket.io-client";

interface Delivery {
  _id: string;
  customerId: string;
  driverId?: string;
  address: string;
  status: string;
  location: {
    lat: number;
    lng: number;
  };
}

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";
const socket = io("http://localhost:5000"); // Connect to backend socket

const containerStyle = {
  width: '100%',
  height: '450px'
};

// Default center until locations load
const defaultCenter = {
  lat: 6.9271,
  lng: 79.8612
};

const GOOGLE_MAPS_API_KEY = "YOUR_GOOGLE_MAPS_API_KEY"; // <-- Insert your API KEY

export default function DeliveryDetails() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();

  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [driverLocation, setDriverLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const { isLoaded } = useJsApiLoader({
    id: 'google-map-script',
    googleMapsApiKey: GOOGLE_MAPS_API_KEY
  });

  useEffect(() => {
    if (!id) {
      setError("❗ No delivery ID provided in URL.");
      setLoading(false);
      return;
    }

    axios
      .get(`${API_BASE_URL}/api/delivery/${id}`)
      .then((res) => {
        setDelivery(res.data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching delivery details:", err);
        setError("❌ Failed to fetch delivery details");
        setLoading(false);
      });

    // Listen for driver location updates
    socket.on("driverLocationUpdate", (data) => {
      if (data.deliveryId === id) {
        setDriverLocation({ lat: data.lat, lng: data.lng });
      }
    });

    return () => {
      socket.off("driverLocationUpdate");
    };
  }, [id]);

  const onLoad = useCallback(function callback(map: google.maps.Map) {
    // You can access the map instance if needed
  }, []);

  if (loading) return <div>Loading...</div>;
  if (error || !delivery) return <div>{error || "Delivery not found"}</div>;

  const deliveryPosition = delivery.location; // Use lat/lng from database

  return (
    <div style={{ padding: "20px" }}>
      <h2>📦 Delivery Details</h2>

      <p><strong>Customer ID:</strong> {delivery.customerId}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>
      <p><strong>Delivery Address:</strong> {delivery.address}</p>

      <div style={{ marginTop: "20px" }}>
        <button
          onClick={() => navigate("/")}
          style={{
            padding: "10px 20px",
            backgroundColor: "#6c757d",
            color: "#fff",
            border: "none",
            borderRadius: "4px",
            cursor: "pointer",
          }}
        >
          ← Back to Dashboard
        </button>
      </div>

      <div style={{ marginTop: "30px" }}>
        <h3>🗺️ Live Driver and Delivery Location:</h3>

        {isLoaded ? (
          <GoogleMap
            mapContainerStyle={containerStyle}
            center={driverLocation || deliveryPosition || defaultCenter}
            zoom={14}
            onLoad={onLoad}
          >
            {/* Driver's Marker */}
            {driverLocation && (
              <Marker
                position={driverLocation}
                label="Driver"
                icon={{
                  url: "http://maps.google.com/mapfiles/ms/icons/blue-dot.png"
                }}
              />
            )}

            {/* Delivery Address Marker */}
            {deliveryPosition && (
              <Marker
                position={deliveryPosition}
                label="Delivery"
                icon={{
                  url: "http://maps.google.com/mapfiles/ms/icons/red-dot.png"
                }}
              />
            )}
          </GoogleMap>
        ) : (
          <div>Loading Map...</div>
        )}
      </div>
    </div>
  );
}
